public class Book
{
    public int Id { get; set; }
    public int AuthorId { get; set; }

    [Resolver]
    public async Task<Author> GetAuthorAsync(
        [Service] IAuthorRepository repository)
    {
        return await repository.GetByIdAsync(AuthorId);
    }
}

[Query]
[UseProjection]
[UsePaging]
public IQueryable<Book> GetBooks([Service] AppDbContext db)
{
    return db.Books;
}
